actions.script:
if (System.getProperty('purchase.pricing.qa.disposable') != 'true' || !ec.user.isInGroup('ADMIN')) {
  ec.web.response.setStatus(403); ec.web.sendJsonResponse([denied:true]); return
}
if (ec.entity.find('mantle.party.Party').condition('partyId','PR13QA_A_01').disableAuthz().count()) {
  ec.web.response.setStatus(409); ec.web.sendJsonResponse([denied:true]); return
}
['security','groups','directory','history'].each { fixture ->
  ec.entity.makeDataLoader().location('component://zenith-erp-contacts/ContactsReference-' + fixture + '.xml').load()
}
if (ec.message.hasError()) throw new IllegalStateException('Synthetic fixture failed')
def demo=ec.entity.find('moqui.security.UserAccount').condition('userId','EX_JOHN_DOE').one()
['CITEST_P14_USER_A','CITEST_P14_USER_NULL','CITEST_P14_USER_EMPTY','CITEST_P14_USER_NA'].each { id ->
  def user=ec.entity.find('moqui.security.UserAccount').condition('userId',id).one()
  ['currentPassword','passwordSalt','passwordHashType','passwordBase64'].each { user.set(it,demo.get(it)) }
  user.disabled='N'; user.requirePasswordChange='N'; user.update()
}
ec.web.sendJsonResponse([initialized:true])

if (System.getProperty('purchase.pricing.qa.disposable') != 'true' || !ec.user.isInGroup('ADMIN') || !['CITEST_ORG_A','NONE'].contains(ec.web.parameters.org)) {
  ec.web.response.setStatus(403); ec.web.sendJsonResponse([denied:true]); return
}
ec.user.setPreference('ACTIVE_ORGANIZATION', ec.web.parameters.org == 'NONE' ? null : ec.web.parameters.org)
ec.web.sendJsonResponse([scope:ec.web.parameters.org])
